#define TWAIFD_TXBHCI_INT_ST    (BIT(11))
#define TWAIFD_TXBHCI_INT_ST_M  (TWAIFD_TXBHCI_INT_ST_V << TWAIFD_TXBHCI_INT_ST_S)
#define TWAIFD_TXBHCI_INT_ST_V  0x00000001U
#define TWAIFD_TXBHCI_INT_ST_S  11

